INSERT INTO calendar_accounts ( id, owner_id, email_link_id, provider, provider_account_id ) VALUES ($1, $2, $3, 'google', $4) ON CONFLICT (email_link_id) DO UPDATE SET owner_id = EXCLUDED.owner_id, provider_account_id = EXCLUDED.provider_account_id, sync_status = CASE WHEN calendar_accounts.sync_status = 'disabled' THEN 'pending' ELSE calendar_accounts.sync_status END, last_sync_error = CASE WHEN calendar_accounts.sync_status = 'disabled' THEN NULL ELSE calendar_accounts.last_sync_error END, updated_at = now() RETURNING id
